import{_t as e,it as t,n,rt as r}from"./chunks/framework.B5d4da8a.js";var i=JSON.parse(`{"title":"Handl SDK Generator — TypeScript Declaration (.d.ts) Backend — design detail","description":"","frontmatter":{"title":"Handl SDK Generator — TypeScript Declaration (.d.ts) Backend — design detail","type":"design","date":"2026-10-28T00:00:00.000Z","updated":"2026-10-29T00:00:00.000Z","refs":["ADR-0115"]},"headers":[],"relativePath":"web/project/design/0115-handl-sdkgen-dts-js.md","filePath":"vendored/web/project/design/0115-handl-sdkgen-dts-js.md"}`),a={name:`web/project/design/0115-handl-sdkgen-dts-js.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="handl-sdk-generator-—-typescript-declaration-d-ts-backend-—-design-detail" tabindex="-1">Handl SDK Generator — TypeScript Declaration (.d.ts) Backend — design detail <a class="header-anchor" href="#handl-sdk-generator-—-typescript-declaration-d-ts-backend-—-design-detail" aria-label="Permalink to “Handl SDK Generator — TypeScript Declaration (.d.ts) Backend — design detail”">​</a></h1><p>Moved verbatim from ADR-0115 (ADR-0161 size budget). The ADR carries the rules; this page carries the full record.</p><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to “Context”">​</a></h2><p><a href="./0107-handl-sdk-generator.html">ADR-0107 — Handl SDK Generator</a> established a backend-agnostic <code>SdkgenModule</code> IR and a port-adapter emitter. The C backend (<code>plugin-sdkgen-backend-c</code>) is implemented, and the WebIDL/JS backend (<a href="./0113-handl-sdkgen-webidl-js.html">ADR-0113</a>) is the next high-priority target for Web platform APIs.</p><p>Web <strong>platform</strong> APIs are typically described by WebIDL, but the bulk of the web ecosystem — libraries, UI frameworks, and server runtimes — is distributed as NPM packages with TypeScript declaration files (<code>.d.ts</code>). Those declarations are already the de-facto machine-readable interface contract for JavaScript code.</p><p>The existing <code>js</code> client package (<code>handl-packages/js/js.hnl</code>) provides the runtime primitives (<code>js.call</code>, <code>js.error</code>) that any generated JS adapter needs. The missing piece is a generator that turns <code>.d.ts</code> descriptions into the same port/adapter Handl source that the other SDKgen backends produce.</p><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to “Decision”">​</a></h2><p>Add a <code>plugin-sdkgen-backend-dts</code> crate that parses TypeScript declaration files and produces <code>SdkgenModule</code> records.</p><ul><li><p>The backend consumes one or more <code>.d.ts</code> files (e.g. from an NPM package&#39;s <code>types</code> field, from DefinitelyTyped, or from a project bundle).</p></li><li><p>The <code>client_package</code> for the generated adapter is <code>js</code>, reusing the primitives from <a href="./0113-handl-sdkgen-webidl-js.html">ADR-0113</a>.</p></li><li><p>The backend maps <code>.d.ts</code> concepts to Handl types and arrows:</p><table tabindex="0"><thead><tr><th>TS concept</th><th>Handl port concept</th><th>Adapter descriptor</th><th>Notes</th></tr></thead><tbody><tr><td><code>number</code></td><td><code>Int</code> or <code>Float</code></td><td><code>js_number</code> / <code>js_int</code> / <code>js_float</code></td><td>heuristically disambiguated by name and JSDoc; overridable in <code>.sdkgen.yaml</code></td></tr><tr><td><code>string</code></td><td><code>String</code></td><td><code>js_string</code></td><td></td></tr><tr><td><code>boolean</code></td><td><code>Bool</code></td><td><code>js_bool</code></td><td></td></tr><tr><td><code>Array&lt;T&gt;</code> / <code>T[]</code></td><td><code>Array</code></td><td><code>js_array:&lt;el&gt;</code></td><td>recursive descriptor</td></tr><tr><td><code>Uint8Array</code> / <code>Buffer</code></td><td><code>Bytes</code></td><td><code>js_bytes</code></td><td></td></tr><tr><td><code>object</code> / <code>any</code> / interface / class</td><td><code>Handle</code></td><td><code>js_object</code></td><td>opaque reference</td></tr><tr><td>interface / class instance</td><td><code>Obj</code> / <code>Handle</code></td><td><code>js_object</code></td><td>fields are not directly exposed unless the adapter is read-only</td></tr><tr><td><code>void</code></td><td><code>()</code></td><td><code>void</code></td><td></td></tr><tr><td><code>undefined</code> / optional <code>?</code></td><td><code>Option</code></td><td><code>js_optional:&lt;inner&gt;</code></td><td></td></tr><tr><td><code>null</code> / <code>T | null</code></td><td><code>Option</code></td><td><code>js_nullable:&lt;inner&gt;</code></td><td></td></tr><tr><td><code>Promise&lt;T&gt;</code></td><td>graded async arrow</td><td><code>js_promise:&lt;inner&gt;</code></td><td>mapped to a <code>Task</code>/<code>Async</code> arrow once async grades are stable; v1 can emit a callback-style adapter</td></tr><tr><td>function</td><td>arrow</td><td>named <code>export</code></td><td>overloaded signatures get deterministic name mangling</td></tr><tr><td>callback type</td><td>function argument</td><td><code>js_callback:&lt;arity&gt;</code></td><td>emitted as a Handl arrow marshalled to a JS function</td></tr><tr><td><code>enum</code></td><td><code>Int</code> + constants</td><td><code>js_enum:&lt;name&gt;</code></td><td></td></tr><tr><td><code>const</code> / <code>readonly</code></td><td>pure value or constant</td><td><code>js_const</code></td><td>exported as a zero-argument arrow or a typed value</td></tr></tbody></table></li><li><p>The output layout follows the established pattern from ADR-0107:</p><ul><li><strong>Port</strong> — abstract <code>export</code> arrows and types, platform-agnostic.</li><li><strong>Adapter</strong> — concrete <code>export ... :=</code> arrows that call <code>js.call</code> and <code>js.error</code>.</li></ul></li><li><p><code>.d.ts</code> overloads and optional arguments use the same name-mangling / defaulting scheme as the WebIDL backend, with deterministic naming (<code>&lt;module&gt;_&lt;fn&gt;_&lt;arity&gt;</code> or a selected canonical overload when disambiguation is ambiguous).</p></li><li><p>A per-package <code>.sdkgen.yaml</code> provides overrides for information that cannot be recovered from <code>.d.ts</code> alone:</p><ul><li>default vs. named exports,</li><li>mutable classes and stateful methods,</li><li>custom marshalling for unusual types,</li><li>side-effecting module imports,</li><li>whether a function throws (maps to <code>Result&lt;_, JsError&gt;</code>) or returns a raw value.</li></ul></li></ul><h3 id="example-using-an-npm-package-from-handl" tabindex="-1">Example: using an NPM package from Handl <a class="header-anchor" href="#example-using-an-npm-package-from-handl" aria-label="Permalink to “Example: using an NPM package from Handl”">​</a></h3><p>A function-oriented package like <code>express</code> ships <code>.d.ts</code> declarations. Running <code>hnl sdkgen dts</code> over them produces a port and a <code>js</code> adapter, and the resulting Handl source looks like any other imported module:</p><div class="language-handl"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">handl</span><pre class="shiki shiki-themes handl-dark github-light" style="--shiki-dark:#ffffff;--shiki-light:#24292e;--shiki-dark-bg:#2a2a2a;--shiki-light-bg:#fff;" tabindex="0" dir="ltr"><code><span class="line"><span>from &quot;npm:express&quot; import { express, get, listen, response_send }</span></span>
<span class="line"><span></span></span>
<span class="line"><span>app = express()</span></span>
<span class="line"><span></span></span>
<span class="line"><span>get(app, &quot;/&quot;, (req, res) ~[JS]~&gt; do {</span></span>
<span class="line"><span>  response_send(res, &quot;hello&quot;)</span></span>
<span class="line"><span>})</span></span>
<span class="line"><span></span></span>
<span class="line"><span>listen(app, 3000)</span></span></code></pre></div><p>The generated adapter is also ordinary Handl (simplified):</p><div class="language-handl"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">handl</span><pre class="shiki shiki-themes handl-dark github-light" style="--shiki-dark:#ffffff;--shiki-light:#24292e;--shiki-dark-bg:#2a2a2a;--shiki-light-bg:#fff;" tabindex="0" dir="ltr"><code><span class="line"><span>export express: () ~[JS]~&gt; Express :=</span></span>
<span class="line"><span>  () ~&gt; call(&quot;express&quot;, &quot;&quot;, [], [], &quot;js_object&quot;, false)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>export get: (Express, String, Handler) ~[JS]~&gt; () :=</span></span>
<span class="line"><span>  (app, path, handler) ~&gt; call(&quot;express&quot;, &quot;get&quot;, [app, path, handler], [&quot;js_object&quot;, &quot;js_string&quot;, &quot;js_callback:2&quot;], &quot;void&quot;, false)</span></span></code></pre></div><p><code>from &quot;npm:express&quot;</code> is not special syntax — it is simply the generated package path that <code>hnl sdkgen dts</code> emitted from the <code>.d.ts</code> files plus any <code>.sdkgen.yaml</code> overrides.</p><h3 id="function-libraries-vs-component-frameworks" tabindex="-1">Function libraries vs. component frameworks <a class="header-anchor" href="#function-libraries-vs-component-frameworks" aria-label="Permalink to “Function libraries vs. component frameworks”">​</a></h3><p>This works well for function/value-oriented packages: Express, Lodash, Axios, <code>fs</code>, <code>crypto</code>, etc.</p><p>It does <strong>not</strong> automatically make React, Vue, or Svelte usable the way they are in JavaScript. <code>.d.ts</code> files do not contain JSX, and the component/reactivity model is framework-specific. Those libraries are still reachable at the low level (<code>createElement</code>, <code>useState</code>, etc.), but a real &quot;React in Handl&quot; experience requires an additional Handl-side component/reactivity layer above the generated <code>js</code> adapters.</p><h3 id="scope-and-limitations" tabindex="-1">Scope and limitations <a class="header-anchor" href="#scope-and-limitations" aria-label="Permalink to “Scope and limitations”">​</a></h3><p>The first version targets the subset of <code>.d.ts</code> that is sufficient for NPM libraries and server frameworks: modules, namespaces, interfaces, type aliases, function and method declarations, constants, enums, and callback types.</p><p>Out of scope for the first version:</p><ul><li>Generics other than monomorphization of a few common instantiations (<code>Array&lt;string&gt;</code>, <code>Promise&lt;number&gt;</code>, etc.).</li><li>Conditional, mapped, template-literal, and recursive conditional types.</li><li>JSX/component view syntax and <code>.hfc</code> packaging — these are not part of <code>.d.ts</code> parsing; see ADR-0116 and ADR-0117.</li><li>Class inheritance, <code>abstract</code> classes, and <code>protected</code>/<code>private</code> members.</li><li>Module augmentation and ambient module declarations.</li></ul><p>These are not blocked by the architecture; they are intentionally deferred to keep the first backend focused on function/value interop.</p><h3 id="parser-choice" tabindex="-1">Parser choice <a class="header-anchor" href="#parser-choice" aria-label="Permalink to “Parser choice”">​</a></h3><p>The backend wraps a <code>.d.ts</code> parser behind the <code>SdkgenBackend</code> trait. The first implementation candidate is a Rust-based TypeScript parser (e.g. <code>swc</code>, <code>oxc_parser</code>, or <code>tree-sitter-typescript</code>). The parser crate is a private dependency of <code>plugin-sdkgen-backend-dts</code>; changing it does not affect the public <code>SdkgenBackend</code> API or the emitted Handl source. A parser evaluation and selection step is part of Phase 0.</p><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to “Consequences”">​</a></h2><ul><li>The large JavaScript ecosystem becomes reachable from Handl without manual adapter authorship for every package.</li><li>Component ergonomics (<code>.hfc</code> and <code>view</code> syntax) are handled separately by ADR-0116 and ADR-0117; the <code>.d.ts</code> backend only supplies the low-level <code>npm:&lt;package&gt;</code> adapter that those layers consume.</li><li><code>.d.ts</code> is richer and more heterogeneous than WebIDL or C headers; the backend will need pragmatic subsetting and a generous override mechanism.</li><li>Structural typing and advanced TS features do not map one-to-one to Handl&#39;s nominal/arrow model; documentation must set expectations about the supported subset.</li><li>The WebIDL and <code>.d.ts</code> backends share the same <code>js</code> client package and adapter pattern, so fixes and improvements to <code>js.call</code>/<code>js.error</code> benefit both.</li><li>Tooling can generate a <code>from &quot;npm:&lt;package&gt;&quot; import *</code> style surface, but the underlying mechanism is still SDKgen + the <code>js</code> client; the runtime import path is determined by the generated adapter, not by Handl&#39;s module loader.</li></ul><h2 id="references" tabindex="-1">References <a class="header-anchor" href="#references" aria-label="Permalink to “References”">​</a></h2><ul><li><a href="./0107-handl-sdk-generator.html">ADR-0107 — Handl SDK Generator</a></li><li><a href="./0113-handl-sdkgen-webidl-js.html">ADR-0113 — Handl SDK Generator: WebIDL / JS Backend</a></li><li><code>handl-packages/js/js.hnl</code> — the JS client package</li><li><code>crates/plugin-sdkgen</code> — the SDK generator core</li></ul>`,29)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};